  );
}

/** Subscribe/emit/unsubscribe, handler isolation and `subscriberCount`. */
import { afterEach, describe, expect, it, vi } from "vitest";
import {
  emit,
  emitAndForget,
  onHandlerError,
  resetEventBus,
  subscribe,
  subscribeOnce,
  subscriberCount,
} from "@/lib/event-bus";
import type { IssueId, IsoTimestamp, ProjectId } from "@/types/common";
import type { TaskflowEventMap } from "@/types/event";
import { ALICE, ORG_A } from "../helpers/factories";

function issueCreated(
  title = "Fix the sign-up link",
): TaskflowEventMap["issue.created"] {
  return {
    orgId: ORG_A,
    actorId: ALICE,
    occurredAt: "2026-03-15T12:00:00.000Z" as IsoTimestamp,
    issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
    projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId,
    title,
    assigneeId: null,
    priority: "medium",
  };
}

afterEach(() => {
  resetEventBus();
});

describe("lib/event-bus", () => {
  it("delivers a payload to every subscriber of that type only", async () => {
    const onCreated = vi.fn();
    const onArchived = vi.fn();
    subscribe("issue.created", onCreated);
    subscribe("issue.archived", onArchived);

    await emit("issue.created", issueCreated());

    expect(onCreated).toHaveBeenCalledTimes(1);
    expect(onCreated.mock.calls[0]?.[0]).toMatchObject({ title: "Fix the sign-up link" });
    expect(onArchived).not.toHaveBeenCalled();
  });

  it("is a no-op when nothing subscribes", async () => {
    await expect(emit("issue.created", issueCreated())).resolves.toBeUndefined();
    expect(subscriberCount("issue.created")).toBe(0);
  });

  it("stops delivering after the returned unsubscribe is called", async () => {
    const handler = vi.fn();
    const off = subscribe("issue.created", handler);
    expect(subscriberCount("issue.created")).toBe(1);

    off();
    expect(subscriberCount("issue.created")).toBe(0);
    await emit("issue.created", issueCreated());
    expect(handler).not.toHaveBeenCalled();
  });

  it("delivers a `subscribeOnce` handler exactly once", async () => {
    const handler = vi.fn();
    subscribeOnce("issue.created", handler);

    await emit("issue.created", issueCreated("first"));
    await emit("issue.created", issueCreated("second"));

    expect(handler).toHaveBeenCalledTimes(1);
    expect(subscriberCount("issue.created")).toBe(0);
  });

  it("isolates a throwing handler: siblings still run and emit resolves", async () => {
    const sink = vi.fn();
    onHandlerError(sink);
    subscribe("issue.created", () => {
      throw new Error("handler exploded");
    });
    const survivor = vi.fn();
    subscribe("issue.created", survivor);

    await expect(emit("issue.created", issueCreated())).resolves.toBeUndefined();
    expect(survivor).toHaveBeenCalledTimes(1);
    expect(sink).toHaveBeenCalledTimes(1);
    expect(sink.mock.calls[0]?.[0]).toBe("issue.created");
  });

  it("reports a rejected async handler to the error sinks", async () => {
    const sink = vi.fn();
    onHandlerError(sink);
    subscribe("issue.created", async () => {
      await Promise.reject(new Error("async boom"));
    });

    await emit("issue.created", issueCreated());
    expect(sink).toHaveBeenCalledTimes(1);
  });

  it("awaits async handlers before resolving", async () => {
    const order: string[] = [];
    subscribe("issue.created", async () => {
      await new Promise((resolve) => setTimeout(resolve, 5));
      order.push("handler");
    });

    await emit("issue.created", issueCreated());
    order.push("after-emit");
    expect(order).toEqual(["handler", "after-emit"]);
  });

  it("emitAndForget returns synchronously but still delivers", async () => {
    const handler = vi.fn();
    subscribe("issue.created", handler);

    expect(emitAndForget("issue.created", issueCreated())).toBeUndefined();
    await Promise.resolve();
    await Promise.resolve();
    expect(handler).toHaveBeenCalledTimes(1);
  });

  it("counts each distinct handler once", () => {
    const handler = vi.fn();
    subscribe("issue.created", handler);
    subscribe("issue.created", handler);
    expect(subscriberCount("issue.created")).toBe(1);

    subscribe("issue.created", vi.fn());
    expect(subscriberCount("issue.created")).toBe(2);
  });
});

/**
 * Wires every subscriber at process start. Called once from `src/instrumentation.ts`; the only module that knows the full listener set.
 *
 * Must call (do not reimplement): subscribe, registerActivityListeners, registerSearchListeners, registerUsageListeners, registerWebhookListeners
 */
import { subscribe } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import { enqueue } from "@/server/jobs/queue";
import { toIsoTimestamp } from "@/types/common";
import { registerActivityListeners } from "./activity-service";
import { registerSearchListeners } from "./search-service";
import { registerUsageListeners } from "./usage-service";
import { registerWebhookListeners } from "./webhook-service";
import type { Unsubscribe } from "@/types/event";

/**
 * Importing this module also loads `notification-service` transitively, which
 * attaches the notification fan-out on first import — that hub has no
 * `register*` entry point of its own.
 */
import "./notification-service";

const logger = createLogger("event-registry");

/** Non-null between `registerEventHandlers()` and `unregisterEventHandlers()`. */
let detach: Unsubscribe | null = null;

/**
 * Attaches every subscriber exactly once. Idempotent: `instrumentation.ts`
 * runs per server process, but a hot reload in dev can call it again and must
 * not double-deliver every event.
 */
export function registerEventHandlers(): void {
  if (detach !== null) return;

  const offs: Unsubscribe[] = [
    registerActivityListeners(),
    registerSearchListeners(),
    registerUsageListeners(),
    registerWebhookListeners(),
    registerDigestBridge(),
  ];

  detach = () => {
    for (const off of offs) off();
  };

  logger.info("event handlers registered", { groups: offs.length });
}

export function unregisterEventHandlers(): void {
  detach?.();
  detach = null;
}

/**
 * The one piece of wiring that belongs to no single service: turning a
 * `digest.due` event into a queued job. Keeping it here rather than inside
 * `DigestService` stops the service layer from depending on the job layer.
 */
function registerDigestBridge(): Unsubscribe {
  return subscribe("digest.due", (payload) => {
    enqueue({
      id: `digest:${payload.orgId}:${payload.recipientId}`,
      kind: "digest-email",
      runAt: toIsoTimestamp(new Date()),
      attempts: 0,
      payload: {
        orgId: payload.orgId,
        recipientId: payload.recipientId,
        windowStart: payload.windowStart,
      },
    });
  });
}
